export interface Curator { readonly id: string; readonly name: string; }
export interface Collection { readonly id: string; readonly title: string; }
export interface Assignment { readonly id: string; readonly curatorId: string; readonly collectionId: string; }
export interface Artifact { readonly id: string; readonly label: string; readonly assignmentId: string; }
export interface ArtifactReport {
  readonly artifactId: string;
  readonly artifactLabel: string;
  readonly curatorName: string;
  readonly collectionTitle: string;
}

export class ArchiveDirectory {
  private readonly curators: Curator[];
  private readonly collections: Collection[];
  private readonly assignments: Assignment[];
  private readonly artifacts: Artifact[];

  constructor(curators: readonly Curator[], collections: readonly Collection[], assignments: readonly Assignment[], artifacts: readonly Artifact[]) {
    const copyUnique = <T extends { readonly id: string }>(items: readonly T[]): T[] => {
      const seen = new Set<string>();
      return items.map(item => {
        if (item.id.trim() === "" || seen.has(item.id)) throw new TypeError("Blank or duplicate id");
        seen.add(item.id);
        return Object.freeze({ ...item }) as T;
      });
    };
    this.curators = copyUnique(curators);
    this.collections = copyUnique(collections);
    this.assignments = copyUnique(assignments);
    this.artifacts = copyUnique(artifacts);
    for (const assignment of this.assignments) {
      if (!this.curators.some(c => c.id === assignment.curatorId) || !this.collections.some(c => c.id === assignment.collectionId)) {
        throw new TypeError("Broken assignment reference");
      }
    }
    for (const artifact of this.artifacts) {
      if (!this.assignments.some(a => a.id === artifact.assignmentId)) throw new TypeError("Broken artifact reference");
    }
  }

  findCurator(id: string): Curator | undefined {
    const curator = this.curators.find(item => item.id === id);
    return curator === undefined ? undefined : Object.freeze({ ...curator });
  }

  listCurators(): readonly Curator[] {
    return Object.freeze(this.curators.map(item => Object.freeze({ ...item })));
  }

  curatorsForCollection(collectionId: string): readonly Curator[] {
    return Object.freeze(this.assignments
      .filter(item => item.collectionId === collectionId)
      .map(item => this.curators.find(curator => curator.id === item.curatorId)!)
      .map(item => Object.freeze({ ...item })));
  }

  artifactReports(): readonly ArtifactReport[] {
    return Object.freeze(this.artifacts.map(artifact => {
      const assignment = this.assignments.find(item => item.id === artifact.assignmentId)!;
      const curator = this.curators.find(item => item.id === assignment.curatorId)!;
      const collection = this.collections.find(item => item.id === assignment.id)!;
      return Object.freeze({
        artifactId: artifact.id,
        artifactLabel: artifact.label,
        curatorName: curator.name,
        collectionTitle: collection.title
      });
    }));
  }
}

