import { ArchiveDirectory, ArtifactReport, Curator } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectTypeError(action: () => void, message: string): void {
  let thrown: unknown;
  try { action(); } catch (error) { thrown = error; }
  assert(thrown instanceof TypeError, message);
}
function report(actual: ArtifactReport, artifactId: string, artifactLabel: string, curatorName: string, collectionTitle: string): void {
  equal(actual.artifactId, artifactId, `${artifactId} ID`);
  equal(actual.artifactLabel, artifactLabel, `${artifactId} label`);
  equal(actual.curatorName, curatorName, `${artifactId} curator`);
  equal(actual.collectionTitle, collectionTitle, `${artifactId} collection`);
  assert(Object.isFrozen(actual), `${artifactId} report is frozen`);
}

const curatorInputs = [
  { id: "c1", name: "Ada" },
  { id: "c2", name: "Grace" }
];
const collectionInputs = [
  { id: "col1", title: "Origins" },
  { id: "col2", title: "Futures" }
];
const assignmentInputs = [
  { id: "a1", curatorId: "c2", collectionId: "col1" },
  { id: "a2", curatorId: "c1", collectionId: "col1" },
  { id: "a3", curatorId: "c2", collectionId: "col1" },
  { id: "a4", curatorId: "c1", collectionId: "col2" }
];
const artifactInputs = [
  { id: "p2", label: "Second", assignmentId: "a4" },
  { id: "p1", label: "First", assignmentId: "a1" }
];
const directory = new ArchiveDirectory(curatorInputs, collectionInputs, assignmentInputs, artifactInputs);
curatorInputs[0].name = "Mutated";
collectionInputs[0].title = "Mutated";
assignmentInputs[0].curatorId = "c1";
artifactInputs[0].label = "Mutated";

const found = directory.findCurator("c1");
assert(found !== undefined, "existing curator is found");
equal(found.name, "Ada", "constructor copied curator record");
assert(Object.isFrozen(found), "found curator copy is frozen");
const foundAgain = directory.findCurator("c1");
assert(foundAgain !== undefined && foundAgain !== found, "findCurator returns a fresh copy");
equal(directory.findCurator("missing"), undefined, "missing curator returns undefined");

const listed = directory.listCurators();
equal(listed.length, 2, "all curators are listed");
equal(listed[0].id, "c1", "curator order is preserved");
equal(listed[1].id, "c2", "second curator order is preserved");
assert(Object.isFrozen(listed[0]) && Object.isFrozen(listed[1]), "listed records are frozen");
const listedAgain = directory.listCurators();
assert(listed[0] !== listedAgain[0], "listCurators returns fresh record copies");

const assigned: readonly Curator[] = directory.curatorsForCollection("col1");
equal(assigned.length, 3, "repeated assignments are retained");
equal(assigned[0].id, "c2", "first assignment order");
equal(assigned[1].id, "c1", "second assignment order");
equal(assigned[2].id, "c2", "repeated curator order");
assert(assigned[0] !== assigned[2], "repeated results are separate frozen copies");
assert(Object.isFrozen(assigned[0]) && Object.isFrozen(assigned[1]) && Object.isFrozen(assigned[2]), "assignment query copies are frozen");
equal(directory.curatorsForCollection("missing").length, 0, "unknown collection query is empty");

const reports = directory.artifactReports();
equal(reports.length, 2, "one report per artifact");
report(reports[0], "p2", "Second", "Ada", "Futures");
report(reports[1], "p1", "First", "Grace", "Origins");
const reportsAgain = directory.artifactReports();
assert(reportsAgain[0] !== reports[0], "report records are freshly allocated");

const empty = new ArchiveDirectory([], [], [], []);
equal(empty.listCurators().length, 0, "empty directory lists no curators");
equal(empty.artifactReports().length, 0, "empty directory reports no artifacts");

expectTypeError(() => { new ArchiveDirectory([{ id: " ", name: "Blank" }], [], [], []); }, "blank record ID is rejected");
expectTypeError(() => { new ArchiveDirectory([{ id: "x", name: "One" }, { id: "x", name: "Two" }], [], [], []); }, "duplicate record ID is rejected");
expectTypeError(() => {
  new ArchiveDirectory([{ id: "c", name: "C" }], [{ id: "col", title: "Col" }], [{ id: "a", curatorId: "missing", collectionId: "col" }], []);
}, "assignment with missing curator is rejected");
expectTypeError(() => {
  new ArchiveDirectory([{ id: "c", name: "C" }], [{ id: "col", title: "Col" }], [{ id: "a", curatorId: "c", collectionId: "missing" }], []);
}, "assignment with missing collection is rejected");
expectTypeError(() => {
  new ArchiveDirectory([], [], [], [{ id: "p", label: "P", assignmentId: "missing" }]);
}, "artifact with missing assignment is rejected");

